const http = require('http');
const fs = require('fs');
const { MongoClient } = require('mongodb');

const PORT = 3000;
const mongoUrl = "mongodb://127.0.0.1:27017";
const dbName = "mydb";

const server = http.createServer(async function (req, res) {
    if (req.url === '/' && req.method === 'GET') {
        res.writeHead(200, { "Content-Type": "text/html" });
        fs.createReadStream('./home.html').pipe(res);
    } 
    else if (req.url === '/server' && req.method === 'POST') {
        let rawData = '';

        req.on('data', function (chunk) {
            rawData += chunk;
        });

        req.on('end', async function () {
            const formData = new URLSearchParams(rawData);

            const name = formData.get('name');
            const password = formData.get('password');
            const age = formData.get('age');
            const mobile = formData.get('mobile');
            const email = formData.get('email');
            const gender = formData.get('gender');
            const state = formData.get('state');
            const skills = formData.getAll('skills').join(', ');

            const userDocument = {
                name,
                password,
                age: Number(age),
                mobile,
                email,
                gender,
                state,
                skills,
                submittedAt: new Date()
            };

            let client;
            try {
                client = new MongoClient(mongoUrl);
                await client.connect();
                const db = client.db(dbName);
                await db.collection("users").insertOne(userDocument);
                console.log("1 document inserted successfully into MongoDB!");
            } catch (err) {
                console.error("MongoDB Error:", err);
            } finally {
                if (client) await client.close();
            }

            res.writeHead(200, { "Content-Type": "text/html" });
            res.write(`
                <!DOCTYPE html>
                <html>
                <head>
                    <title>User Submitted Details</title>
                    <style>
                        body { font-family: Arial, sans-serif; margin: 30px; }
                        table { border-collapse: collapse; width: 400px; margin-top: 10px; }
                        th, td { border: 1px solid #ddd; padding: 10px; text-align: left; }
                        th { background-color: #f2f2f2; }
                        h2 { color: #333; }
                    </style>
                </head>
                <body>
                    <h2>User Submitted Details</h2>
                    <table>
                        <tr><th>Field</th><th>Value</th></tr>
                        <tr><td><strong>Name</strong></td><td>${name}</td></tr>
                        <tr><td><strong>Password</strong></td><td>${password}</td></tr>
                        <tr><td><strong>Age</strong></td><td>${age}</td></tr>
                        <tr><td><strong>Mobile Number</strong></td><td>${mobile}</td></tr>
                        <tr><td><strong>Email</strong></td><td>${email}</td></tr>
                        <tr><td><strong>Gender</strong></td><td>${gender}</td></tr>
                        <tr><td><strong>State</strong></td><td>${state}</td></tr>
                        <tr><td><strong>Skills</strong></td><td>${skills}</td></tr>
                    </table>
                    <br>
                    <a href="/">Back to Form</a>
                </body>
                </html>
            `);
            res.end();
        });
    } else {
        res.writeHead(404, { "Content-Type": "text/plain" });
        res.end("Page Not Found");
    }
});

server.listen(PORT, function () {
    console.log(`Server is running at http://localhost:${PORT}`);
});